		animation-delay: -1.8s;
	}

	.animated .from,
	.animated .to {
		animation-play-state: running;
	}

	@keyframes forest-hop-out {
		0% {
			opacity: 1;
		}
		70% {
			opacity: 0;
		}
	}

	@keyframes forest-hop-in {
		0% {
			opacity: 0;
		}
		70% {
			opacity: 1;
		}
	}

	@media (prefers-reduced-motion: reduce) {
		.from,
		.to {
			animation: none;
		}
	}
